const b = $input.first().json.body || $input.first().json;

if (!b.siteId) throw new Error('Missing required field: siteId');
if (!b.message) throw new Error('Missing required field: message');

const msg = b.message.toLowerCase().trim();
const actionWords = /\b(implement|create|add|build|make|fix|update|change|edit|delete|remove|install|modify|replace|refactor|style|redesign|adjust|set|configure|enable|disable|write|code)\b/;
const questionWords = /^(what|why|how|can you|could you|should|is it|explain|describe|tell me)/;
const isQuestion = questionWords.test(msg);
const isActionIntent = actionWords.test(msg) && !isQuestion;

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anon',
    message: b.message.trim(),
    requestId: 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    image: b.image || null,
    isActionIntent,
    isQuestion
  }
}];

const inp = $('Validate & Detect Intent').item.json;
const rawSite = $input.first().json;

let site = Array.isArray(rawSite) ? rawSite[0] : (rawSite?.id ? rawSite : rawSite?.data?.[0]);
if (!site?.id) throw new Error('Site not found for siteId: ' + inp.siteId);

// Extract GitHub Token: Prefer User Token, fallback to hardcoded System Token
const SYSTEM_GITHUB_TOKEN = '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';
let githubToken = (site.access_token && site.access_token.trim()) || SYSTEM_GITHUB_TOKEN;

// Use siteKey for preview URL (subdomain-safe), fallback to site_key column or inp.siteId
const siteKey = site.site_key || inp.siteId;

const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) throw new Error('Invalid GitHub repo URL');

const owner = repoMatch[1];
const repo = repoMatch[2].replace(/\.git$/, '');
const msg = inp.message.toLowerCase();

const fileScores = new Map();
const addFile = (file, score) => fileScores.set(file, (fileScores.get(file) || 0) + score);

if (/shop|brand|name|title|logo/.test(msg)) {
  addFile('src/components/Header.tsx', 15);
  addFile('src/app/layout.tsx', 10);
  addFile('src/components/Footer.tsx', 8);
}
if (/color|theme|style|css|dark|light/.test(msg)) {
  addFile('src/app/globals.css', 10);
  addFile('tailwind.config.ts', 7);
}
if (/header|nav|menu/.test(msg)) addFile('src/components/Header.tsx', 12);
if (/footer/.test(msg)) addFile('src/components/Footer.tsx', 10);
if (/hero/.test(msg)) addFile('src/components/Hero.tsx', 10);
if (/page|home|landing/.test(msg) || fileScores.size === 0) addFile('src/app/page.tsx', 10);

const sortedFiles = [...fileScores.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([f]) => f);
if (sortedFiles.length === 0) sortedFiles.push('src/app/page.tsx');

return [{
  json: {
    ...inp,
    site: { id: siteKey, uuid: site.id, name: site.name || 'Unknown', repo_url: site.repo_url, branch: site.default_branch || 'main' },
    owner, repo,
    branch: site.default_branch || 'main',
    previewUrl: 'https://' + siteKey + '.preview.automatelb.com',
    filesToFetch: sortedFiles,
    fileContents: {},
    contextFiles: [],
    githubToken: githubToken
  }
}];

const ctx = $('Build Context').item.json;
const files = ctx.filesToFetch || [];
if (files.length === 0) return [{ json: { ...ctx, currentFile: null } }];

return files.map(f => ({
  json: {
    _ctx: { ...ctx },
    currentFile: f,
    owner: ctx.owner,
    repo: ctx.repo,
    branch: ctx.branch,
    githubToken: ctx.githubToken
  }
}));

const items = $input.all();
const prepItems = $('Prepare Fetch').all();
const ctx = prepItems[0]?.json?._ctx;
if (!ctx) throw new Error('Lost context');

const fileContents = {};
const contextFiles = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const path = prepItems[i]?.json?.currentFile || item.path;
  if (!path) continue;

  if (item.content) {
    try {
      const decoded = Buffer.from(item.content, 'base64').toString('utf8');
      fileContents[path] = decoded.length > 4000 ? decoded.substring(0, 4000) + '\n// ... truncated' : decoded;
      contextFiles.push(path);
    } catch (e) {}
  }
}

return [{ json: { ...ctx, fileContents, contextFiles } }];

// Fetch recent memory for this project from Supabase
const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
const requestId = ctx.requestId || 'unknown';
const conversationId = ctx.conversationId || null;

if (!siteId) {
  console.log('No site UUID found, skipping memory fetch');
  return [{ json: { ...ctx, memoryContext: '' } }];
}

// Insert initial thinking step
try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
      request_id: requestId,
      site_id: siteId,
      conversation_id: conversationId,
      step_number: 1,
      tool_name: 'analyze',
      status: 'running',
      message: 'Analyzing your request...',
      details: { message: ctx.message }
    }),
    timeout: 5000
  });
} catch (e) {
  console.error('Failed to insert thinking step:', e.message);
}

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/agent_memory?project_id=eq.' + siteId + '&order=created_at.desc&limit=15',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4'
    },
    timeout: 10000
  });

  let memoryContext = '';
  if (Array.isArray(response) && response.length > 0) {
    memoryContext = 'PREVIOUS REQUESTS (most recent is LAST):\n\n';
    memoryContext += response.reverse().map(function(entry, i) {
      const data = entry.content_json || {};
      const msg = data.message || entry.content || '';
      const summary = data.summary || '';
      const files = (data.filesModified || []).concat(data.filesCreated || []).join(', ');
      let result = '**[Request ' + (i + 1) + ']** "' + msg.substring(0, 200) + '"';
      result += '\n  Result: ' + summary.substring(0, 300);
      if (files) result += '\n  Files: ' + files;
      return result;
    }).join('\n\n');
    console.log('Fetched ' + response.length + ' memory entries');
  }

  return [{ json: { ...ctx, memoryContext: memoryContext } }];
} catch (e) {
  console.error('Memory fetch failed:', e.message);
  return [{ json: { ...ctx, memoryContext: '' } }];
}

const rawInput = $fromAI('query', 'Directory path', 'string') || '';
let dir = rawInput.trim() || 'src';

if (dir.startsWith('{')) {
  try { const p = JSON.parse(dir); dir = p.path || p.directory || 'src'; } catch {}
}

const ctx = $('Merge Files')?.item?.json || {};
const owner = ctx.owner;
const repo = ctx.repo;
const branch = ctx.branch || 'main';
const githubToken = ctx.githubToken;

if (!owner || !repo || !githubToken) return 'Error: No repository context';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/repos/' + owner + '/' + repo + '/contents/' + dir + '?ref=' + branch,
    headers: {
      'Authorization': 'Bearer ' + githubToken,
      'Accept': 'application/vnd.github+json'
    },
    timeout: 15000
  });
  if (Array.isArray(response)) {
    return response.map(f => f.path + (f.type === 'dir' ? '/' : '')).join('\n');
  }
  return JSON.stringify(response);
} catch (e) {
  return 'Error listing files: ' + e.message;
}

const rawInput = $fromAI('query', 'File path to read', 'string') || '';
let file = rawInput.trim();

if (file.startsWith('{')) {
  try { const p = JSON.parse(file); file = p.path || p.file || ''; } catch {}
}

if (!file) return 'Error: File path required';

const ctx = $('Merge Files')?.item?.json || {};
const owner = ctx.owner;
const repo = ctx.repo;
const branch = ctx.branch || 'main';
const githubToken = ctx.githubToken;

if (!owner || !repo || !githubToken) return 'Error: No repository context';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/repos/' + owner + '/' + repo + '/contents/' + file + '?ref=' + branch,
    headers: {
      'Authorization': 'Bearer ' + githubToken,
      'Accept': 'application/vnd.github.v3.raw'
    },
    timeout: 15000
  });
  return typeof response === 'string' ? response : JSON.stringify(response);
} catch (e) {
  return 'Error reading file: ' + e.message;
}

const rawInput = $fromAI('query', 'filePath|||fileContent', 'string') || '';
const idx = rawInput.indexOf('|||');
if (idx === -1) return 'Error: Invalid format. Use: filePath|||fileContent';

const filePath = rawInput.substring(0, idx).trim();
const content = rawInput.substring(idx + 3);
if (!filePath) return 'Error: File path required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
const githubToken = ctx.githubToken;
if (!siteId) return 'Error: No site context';

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/write',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, filePath, content, githubToken }),
    timeout: 30000,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true
  });

  const body = response.body;
  // Check if status is error OR if body indicates failure (missing both success and ok)
  if (response.statusCode >= 400 || (body && !body.success && !body.ok)) {
     const debugInfo = {
       status: response.statusCode,
       sent: { siteId, filePath, contentLen: content?.length },
       response: body
     };
     return 'Error: Orchestrator ' + response.statusCode + ' - ' + JSON.stringify(debugInfo);
  }

  return JSON.stringify({ success: true, file: filePath, action: 'created' });
} catch (e) {
  return 'Error: Exception - ' + e.message;
}

const rawInput = $fromAI('query', 'filePath|||searchText|||replaceText', 'string') || '';
const parts = rawInput.split('|||');
if (parts.length !== 3) return 'Error: Invalid format. Use: filePath|||searchText|||replaceText';

const [filePath, search, replace] = parts.map(p => p.trim());
if (!filePath || !search) return 'Error: File path and search text required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
const githubToken = ctx.githubToken;
if (!siteId) return 'Error: No site context';

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/replace',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, filePath, search, replace, githubToken }),
    timeout: 30000,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true
  });

  const body = response.body;
  // Check if status is error OR if body indicates failure (missing both success and ok)
  if (response.statusCode >= 400 || (body && !body.success && !body.ok)) {
     const debugInfo = {
       status: response.statusCode,
       sent: { siteId, filePath, searchLen: search?.length, replaceLen: replace?.length },
       response: body
     };
     return 'Error: Orchestrator ' + response.statusCode + ' - ' + JSON.stringify(debugInfo);
  }

  return JSON.stringify({ success: true, file: filePath, action: 'replaced' });
} catch (e) {
  return 'Error: Exception - ' + e.message;
}

const rawInput = $fromAI('query', 'File path to delete', 'string') || '';
let file = rawInput.trim();

if (file.startsWith('{')) {
  try { const p = JSON.parse(file); file = p.path || p.file || ''; } catch {}
}

if (!file) return 'Error: File path required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
const githubToken = ctx.githubToken;

if (!siteId || !githubToken) return 'Error: No site context';

try {
  const response = await this.helpers.httpRequest({
    method: 'DELETE',
    url: 'https://preview-orchestrator.fly.dev/preview/file',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, file, githubToken }),
    timeout: 30000
  });
  return JSON.stringify({ success: true, deleted: file });
} catch (e) {
  return 'Error: ' + e.message;
}

const rawInput = $fromAI('query', 'Search pattern', 'string') || '';
let pattern = rawInput.trim();

if (pattern.startsWith('{')) {
  try { const p = JSON.parse(pattern); pattern = p.pattern || p.query || ''; } catch {}
}

if (!pattern) return 'Error: Search pattern required';

const ctx = $('Merge Files')?.item?.json || {};
const owner = ctx.owner;
const repo = ctx.repo;
const githubToken = ctx.githubToken;

if (!owner || !repo || !githubToken) return 'Error: No repository context';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/search/code?q=' + encodeURIComponent(pattern + ' repo:' + owner + '/' + repo),
    headers: {
      'Authorization': 'Bearer ' + githubToken,
      'Accept': 'application/vnd.github+json'
    },
    timeout: 15000
  });
  if (response.items && response.items.length > 0) {
    return response.items.slice(0, 10).map(item => item.path).join('\n');
  }
  return 'No files found matching: ' + pattern;
} catch (e) {
  return 'Error searching: ' + e.message;
}

const rawInput = $fromAI('query', 'Package name', 'string') || '';
let pkg = rawInput.trim();

if (pkg.startsWith('{')) {
  try { const p = JSON.parse(pkg); pkg = p.package || p.name || p.input || ''; } catch {}
}

if (!pkg) return 'Error: Package name required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
if (!siteId) return 'Error: No site context';

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/install',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, packages: [pkg] }),
    timeout: 120000
  });
  return JSON.stringify({ success: true, installed: response.installed || [pkg] });
} catch (e) {
  return 'Error: ' + e.message;
}

// Save memory entry to Supabase for future context
const ctx = $input.item.json;
const siteId = ctx.site?.uuid;

if (!siteId) {
  console.log('No site UUID found, skipping memory save');
  return [{ json: ctx }];
}

const msgPart = (ctx.message || '').substring(0, 200) || 'N/A';
const summaryPart = (ctx.plan?.humanSummary || '').substring(0, 300) || 'N/A';

const memoryEntry = {
  project_id: siteId,
  memory_type: 'conversation',
  content: 'Request: ' + msgPart + ' | Response: ' + summaryPart,
  content_json: {
    message: ctx.message || '',
    summary: ctx.plan?.humanSummary || '',
    filesModified: ctx.filesModified || [],
    filesCreated: ctx.filesCreated || [],
    filesDeleted: ctx.filesDeleted || [],
    toolsUsed: ctx.toolsUsed || [],
    iterations: ctx.iterations || 0,
    requestId: ctx.requestId || null
  }
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/agent_memory',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify(memoryEntry),
    timeout: 10000
  });
  console.log('Memory saved for ' + siteId);
} catch (e) {
  console.error('Memory save failed:', e.message);
}

return [{ json: ctx }];

const ctx = $('Merge Files').item.json;
const raw = $('AI Agent').item.json;

const output = (raw?.output || '').replace(/\*\*/g, '');
const steps = raw?.intermediateSteps || [];

const filesModified = new Set();
const filesCreated = new Set();
const filesDeleted = new Set();
const toolCalls = [];

for (const step of steps) {
  if (step.action?.tool) toolCalls.push(step.action.tool);
  const obs = step.observation;
  let result = null;

  try {
    if (typeof obs === 'object' && obs !== null) {
       result = obs;
    } else if (typeof obs === 'string') {
       // Try parsing if it looks like JSON or contains JSON
       const jsonMatch = obs.match(/\{.*\}/s);
       if (jsonMatch) {
         result = JSON.parse(jsonMatch[0]);
       } else {
         // Try parsing directly
         result = JSON.parse(obs);
       }
    }
  } catch (e) {
    // console.log('Failed to parse observation:', obs);
  }

  if (result && result.success) {
    const file = result.file || result.to;
    if (file) {
      if (result.action === 'created') filesCreated.add(file);
      else if (result.action === 'updated' || result.action === 'replaced') filesModified.add(file);
    }
    if (result.deleted) filesDeleted.add(result.deleted);
  }
}

const warnings = [];
if (filesModified.size === 0 && filesCreated.size === 0 && filesDeleted.size === 0 && steps.length > 2) {
  warnings.push('No files were modified');
}


// Insert completion thinking step
const requestId = ctx.requestId || 'unknown';
const siteId = ctx.site?.id || 'unknown';

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/thinking_steps',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify({
      request_id: requestId,
      site_id: siteId,
      step_number: 999999,
      tool_name: 'complete',
      status: 'complete',
      message: output || 'Request completed',
      details: { filesModified: [...filesModified], filesCreated: [...filesCreated], filesDeleted: [...filesDeleted] }
    }),
    timeout: 5000
  });
} catch (e) {
  console.error('Failed to insert completion step:', e.message);
}

return [{
  json: {
    ...ctx,
    plan: { humanSummary: output, warnings },
    filesModified: [...filesModified],
    filesCreated: [...filesCreated],
    filesDeleted: [...filesDeleted],
    iterations: steps.length,
    toolsUsed: [...new Set(toolCalls)]
  }
}];

// Push changes to GitHub
const ctx = $input.item.json;
const result = $('Parse Results')?.item?.json || {};
const siteId = ctx.site?.id || ctx.site?.uuid;
const githubToken = ctx.githubToken;

if (!siteId) {
  ctx.pushError = 'No siteId found';
  return [{ json: ctx }];
}

// Check if we actually have changes to push
const hasChanges = (result.filesModified?.length > 0 || result.filesCreated?.length > 0 || result.filesDeleted?.length > 0);

if (!hasChanges) {
  ctx.pushSkipped = 'No files changed';
  return [{ json: ctx }];
}

console.log(`🚀 Pushing changes for ${siteId}...`);

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/push',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ 
      siteId, 
      githubToken,
      message: result.plan?.humanSummary || 'AI Automated Update'
    }),
    timeout: 60000,
    json: true,
    ignoreHttpStatusErrors: true,
    returnFullResponse: true
  });

  const body = response.body;
  ctx.pushStatusCode = response.statusCode;
  ctx.pushResult = body;

  if (response.statusCode >= 400) {
    ctx.pushError = 'HTTP ' + response.statusCode + ': ' + JSON.stringify(body);
    console.error(`❌ Git push failed:`, ctx.pushError);
  } else {
    console.log(`✅ Git push success:`, JSON.stringify(body));
  }
} catch (e) {
  ctx.pushError = e.message;
  console.error(`❌ Git push exception:`, e.message);
}

return [{ json: ctx }];

// Pull latest changes from Git to preview workspace
// This syncs the preview with GitHub commits made by the AI
const ctx = $input.item.json;
const siteId = ctx.site?.id;

if (!siteId) {
  console.log('⚠️ No siteId found, skipping git pull');
  return [{ json: ctx }];
}

